WITH joined AS (SELECT s.*, b.discount, b.amount, b.shipping_fee FROM shipments s LEFT JOIN orders b ON s.order_id = b.id), enriched AS (SELECT s.*, b.discount AS order_discount, b.order_date FROM joined s LEFT JOIN orders b ON s.order_id = b.id), remaining_keys AS (SELECT status, carrier FROM enriched EXCEPT DISTINCT SELECT status, carrier FROM shipments WHERE MONTH(shipped_date) IN (4, 9, 10)), kept_rows AS (SELECT s.* FROM enriched s INNER JOIN remaining_keys k ON s.status = k.status AND s.carrier = k.carrier), scored AS (SELECT *, MIN(shipping_fee) OVER w_hist AS order_id_min_shipping_fee, MIN(discount) OVER (PARTITION BY status) AS status_min_discount, PERCENT_RANK() OVER w_grp AS discount_percent_rank, STDDEV_SAMP(shipping_fee) OVER (PARTITION BY order_id, carrier) AS order_id_stddev_samp_shipping_fee FROM kept_rows WINDOW w_hist AS (PARTITION BY order_id), w_grp AS (ORDER BY discount DESC)) SELECT * FROM (SELECT status, shipping_fee, discount_percent_rank, order_discount FROM scored) src UNPIVOT (val FOR metric_name IN (shipping_fee AS SHIPPING_FEE_VAL, discount_percent_rank AS DISCOUNT_PERCENT_RANK_VAL, order_discount));
